const s = $('Start').first().json;
const g = (n) => { try { return $(n).first().json || {}; } catch (e) { return {}; } };
const mine = ["bug_analysis", "security_analysis", "code_quality_analysis", "gap_analysis", "structure_analysis", "consistency_analysis", "plateau_planning_analysis", "change_risk_analysis", "change_impact_analysis", "rewrite_plan"];
// RM GET /pm/project-types/{id}/card-types returns ONE object: {phases:[{phase_id,name,title,output,capabilities:[{name,card_types:[{name,title,is_entry}]}]}]}
const comp = g('Project type card types');
if (!Array.isArray(comp.phases)) throw new Error('Project type card types: no phases in the RM composition for project type ' + s.project_type_id);
const byType = {};
for (const p of comp.phases) {
  for (const c of (p.capabilities || [])) {
    for (const t of (c.card_types || [])) {
      const n = String(t.name || '');
      if (mine.indexOf(n) < 0) continue;
      const d = byType[n] || (byType[n] = { name: n, title: t.title || n, phases_placed: [], entry_in: [] });
      if (d.phases_placed.indexOf(p.name) < 0) d.phases_placed.push(p.name);
      if (t.is_entry && d.entry_in.indexOf(p.name) < 0) d.entry_in.push(p.name);
    }
  }
}
const defs = Object.keys(byType).map(k => byType[k]);
const ph = comp.phases.find(p => p.name === s.phase || String(p.phase_id) === String(s.phase)) || {};
const briefRaw = g('Brief');
const brief = (briefRaw && briefRaw.brief && typeof briefRaw.brief === 'object') ? briefRaw.brief : briefRaw;
const list = (v) => String(v || '').split(',').map(x => x.trim()).filter(x => x !== '');
return [{ json: {
  capability: "analysis", function: "consult",
  tenant_id: s.tenant_id, project_id: s.project_id, project_type_id: s.project_type_id,
  phase: s.phase, phase_detail: { name: ph.name || s.phase, title: ph.title || '', output: ph.output || '' },
  brief_version: s.brief_version, board_id: s.board_id,
  project: g('Project'), brief: brief,
  prior_phase_ids: list(s.prior_phase_ids), pm_purpose: s.pm_purpose || "",
  consulted: list(s.consulted),
  my_card_types: defs, not_in_catalogue: defs.length === 0
} }];

const ctx = $('Context').first().json;
const o = $input.first().json || {};
const a = (o.output && typeof o.output === 'object') ? o.output : o;
const fail = [];
const isStr = (v) => typeof v === 'string' && v.trim() !== '';
const oneOf = (v, xs) => xs.indexOf(v) >= 0;
const allowed = (ctx.my_card_types || []).map(d => String(d.name));
if (!allowed.length) {
  // No card type of this capability is placed in this project type: exactly one answer is valid, and a small
  // model will not reach it reliably, so answer it here instead of spending rule-7 retries on a losing argument.
  return [{ json: Object.assign({}, a, { involvement: 'none', card_types: [], declined: isStr(a.declined) ? a.declined : 'no card types for this capability', status: 'ok', failed_checks: [], execution_id: $execution.id, capability: ctx.capability, function: ctx.function, card_types_allowed: [] }) }];
}
const consulted = ctx.consulted || [];
const capOf = (r) => String((r && typeof r === 'object') ? (r.capability || '') : (r || ''));
const checkConsulted = (rs) => { for (const r of rs) { const c = capOf(r); if (c && (consulted.indexOf(c) < 0 || c === ctx.capability)) fail.push('not_consulted:' + c); } };
if (!oneOf(a.involvement, ['none','light','standard','heavy'])) fail.push('involvement_enum');
if (!oneOf(a.rigor, ['low','medium','high'])) fail.push('rigor_enum');
if (!oneOf(a.complexity, ['low','medium','high'])) fail.push('complexity_enum');
if (a.involvement !== 'none' && !isStr(a.purpose)) fail.push('purpose_empty');
const cts = Array.isArray(a.card_types) ? a.card_types : [];
if (a.involvement === 'none') {
  if (cts.length) fail.push('none_with_card_types');
  if (!isStr(a.declined)) fail.push('declined_empty');
} else if (!cts.length) fail.push('involvement_without_card_types');
for (const c of cts) {
  const t = String((c || {}).card_type || '');
  if (allowed.indexOf(t) < 0) fail.push('card_type_not_in_catalogue:' + t);
  if (!Number.isInteger(c.count) || c.count < 1 || c.count > 10) fail.push('count_invalid:' + t);
  if (!isStr(c.purpose)) fail.push('card_purpose_empty:' + t);
  if (!oneOf(c.when, ['early','mid','late'])) fail.push('when_enum:' + t);
  checkConsulted([].concat(c.needs || [], c.feeds || []));
}
const maxCards = 10;
const total = cts.reduce((s, c) => s + (Number.isInteger((c || {}).count) ? c.count : 0), 0);
if (total > maxCards) fail.push('card_count_over_max');
const io = a.operation_order || {};
checkConsulted([].concat(io.needs || [], io.feeds || []));
const status = (a.decision === 'block') ? 'blocked' : (fail.length ? 'invalid' : 'ok');
return [{ json: Object.assign({}, a, { status: status, failed_checks: fail, execution_id: $execution.id,
  capability: ctx.capability, function: ctx.function, card_types_allowed: allowed }) }];

// No output parser is attached: with one, a parse failure happens inside the
// structured-output attempt and n8n restarts the conversation from the initial
// prompt, discarding every tool result (measured exec 1217916). Extract
// tolerantly here, validate strictly, fail LOUDLY. Never invent.
const first = $input.first().json || {};
const raw = String(first.output ?? first.text ?? '').trim();
const fail = (why) => { throw new Error(`cap.analysis.consult consult envelope unusable: ${why} | head=${raw.slice(0, 240)}`); };
if (!raw) fail('model returned no text');
const fenced = raw.match(/```(?:json)?\s*([\s\S]*?)```/i);
const body = fenced ? fenced[1] : raw;
const start = body.indexOf('{');
const end = body.lastIndexOf('}');
if (start === -1 || end <= start) fail('no JSON object found');
let doc;
try { doc = JSON.parse(body.slice(start, end + 1)); } catch (e) { fail('JSON.parse: ' + e.message); }
const out = (doc && typeof doc === 'object' && doc.output && typeof doc.output === 'object') ? doc.output : doc;
if (!out || typeof out !== 'object' || Array.isArray(out)) fail('parsed value is not an object');
if (out.decision !== 'proceed' && out.decision !== 'block') fail(`decision must be "proceed" or "block", got ${JSON.stringify(out.decision)}`);
for (const k of ['reason', 'comment', 'involvement', 'purpose', 'rigor', 'complexity', 'declined']) if (typeof out[k] !== 'string') fail(`${k} is not a string`);
const oo = out.operation_order;
if (!oo || typeof oo !== 'object' || Array.isArray(oo)) fail('operation_order is not an object');
for (const k of ['needs', 'feeds']) if (!Array.isArray(oo[k])) fail(`operation_order.${k} is not an array`);
for (const k of ['card_types', 'risks', 'questions']) if (!Array.isArray(out[k])) fail(`${k} is not an array`);
// Keep every field the agent emitted (it sees intermediateSteps) and replace only output.
return [{ json: Object.assign({}, first, { output: out }) }];
